as $function$
  select $drill${"key":"ai_usage","fact":"ai_usage_hourly","mode":"definer","grain":"one row per hour for each organization, person, agent, provider, model, app, feature, origin, manual or automated, and source","label":"AI usage","lanes":["platform","organization","mine"],"paths":[{"key":"who","label":"Who","levels":["organization","person"]},{"key":"what","label":"What","levels":["provider","model"]},{"key":"where","label":"Where","levels":["app","feature","agent"]},{"key":"when","label":"When","levels":["at:month","at:week","at:day","at:hour"]}],"views":[{"key":"usage_by_person","label":"Usage by person","question":{"by":["person"],"show":["cost","requests","calls","tokens_total","tokens_in","tokens_out","models","last_activity"],"sort":{"key":"cost","direction":"desc"}}},{"key":"usage_by_person_and_origin","label":"Usage by person and origin","question":{"by":["person"],"show":["cost"],"sort":{"key":"cost","direction":"desc"},"across":"origin"}},{"key":"spend_by_organization","label":"Spend by organization","question":{"by":["organization"],"show":["cost","manual_share","requests","cost_per_request","tokens_in","tokens_cached","tokens_out"],"sort":{"key":"cost","direction":"desc"}}},{"key":"spend_by_person","label":"Spend by person","question":{"by":["person"],"show":["cost","manual_share","requests","cost_per_request","tokens_in","tokens_cached","tokens_out"],"sort":{"key":"cost","direction":"desc"}}},{"key":"spend_by_agent","label":"Spend by agent","question":{"by":["agent"],"show":["cost","manual_share","requests","cost_per_request","tokens_in","tokens_cached","tokens_out"],"sort":{"key":"cost","direction":"desc"}}},{"key":"spend_by_app","label":"Spend by app","question":{"by":["app"],"show":["cost","manual_share","requests","cost_per_request","tokens_in","tokens_cached","tokens_out"],"sort":{"key":"cost","direction":"desc"}}},{"key":"spend_by_feature","label":"Spend by feature","question":{"by":["feature"],"show":["cost","manual_share","requests","cost_per_request","tokens_in","tokens_cached","tokens_out"],"sort":{"key":"cost","direction":"desc"}}},{"key":"spend_by_origin","label":"Spend by how it started","question":{"by":["origin"],"show":["cost","manual_share","requests","cost_per_request","tokens_in","tokens_cached","tokens_out"],"sort":{"key":"cost","direction":"desc"}}},{"key":"spend_by_trigger","label":"Spend by manual or automated","question":{"by":["trigger"],"show":["cost","manual_share","requests","cost_per_request","tokens_in","tokens_cached","tokens_out"],"sort":{"key":"cost","direction":"desc"}}},{"key":"spend_by_source","label":"Spend by execution type","question":{"by":["source"],"show":["cost","manual_share","requests","cost_per_request","tokens_in","tokens_cached","tokens_out"],"sort":{"key":"cost","direction":"desc"}}},{"key":"spend_by_model","label":"Spend by model","question":{"by":["model"],"show":["cost","manual_share","requests","cost_per_request","tokens_in","tokens_cached","tokens_out"],"sort":{"key":"cost","direction":"desc"}}},{"key":"spend_by_day","label":"Spend by day","question":{"by":["at:day"],"show":["cost","requests","tokens_in","tokens_out"],"sort":{"key":"at:day","direction":"asc"}}},{"key":"spend_by_hour","label":"Spend by hour","question":{"by":["at:hour"],"show":["cost","requests","tokens_in","tokens_out"],"sort":{"key":"at:hour","direction":"asc"}}}],"detail":{"open":"/administration/billing/spend","columns":["bucket","organization_id","person_id","provider","model","feature","cost","tokens_in","tokens_out"]},"default":{"by":["person"],"path":"who","show":["cost","requests","tokens_in","tokens_out"],"sort":{"key":"cost","direction":"desc"},"window":{"key":"at","preset":"30d"}},"records":{"fact":"ai_usage_executions","labels":{"model":"Request's top model","provider":"Request's top model's provider","requests":"Request (counted on its first call)","tokens_in":"Request input tokens (on its first call)","call_model":"Model this call billed","created_at":"When","iterations":"Request