abel":"Total tokens","parts":["tokens_in","tokens_cached","tokens_out"],"additive":true},{"of":"bucket","op":"max","key":"last_activity","unit":"time","label":"Last active hour","additive":false},{"of":"unpriced_calls","op":"sum","key":"unpriced_calls","unit":"count","label":"Calls with no price","additive":true},{"of":"person_id","op":"count_distinct","key":"people","unit":"count","label":"People","additive":false},{"of":"model","op":"count_distinct","key":"models","unit":"count","label":"Models","additive":false},{"of":"cost","op":"sum","key":"manual_cost","unit":"usd","label":"Cost someone asked for","where":{"trigger":"manual"},"additive":true},{"op":"ratio","den":"cost","key":"manual_share","num":["manual_cost"],"unit":"share","label":"Share someone asked for","description":"The part of the cost a person or an API caller asked for; the rest ran on its own"},{"op":"ratio","den":"requests","key":"cost_per_request","num":["cost"],"unit":"usd","label":"Cost per request","description":"Cost divided by requests, as the old Spend page's Per request column"}],"dimensions":[{"key":"organization","from":"organization_id","kind":"relation","label":"Organization","relation":{"token":"organization"},"description":"The organization the execution ran under"},{"key":"person","from":"person_id","kind":"relation","label":"Person","level":{"breakouts":["provider","model","agent","feature","at:day"],"attributes":["organization"]},"relation":{"token":"user","person":true},"description":"The signed-in person the request belongs to; a shared login counts everyone using it as one"},{"key":"provider","from":"provider","kind":"choice","label":"Provider","choices":[{"label":"Anthropic","value":"anthropic"},{"label":"Google","value":"google"},{"label":"Moonshot","value":"moonshot"},{"label":"OpenAI","value":"openai"},{"label":"Replicate","value":"replicate"},{"label":"Cerebras","value":"cerebras"},{"label":"Together AI","value":"together"},{"label":"ElevenLabs","value":"elevenlabs"},{"lab